new="""  init_modal() {
    const overlay = this.querySelector('[data-ui-overlay]');
    const dialog = this.querySelector('.xavi-ui-dialog');
    const trigger = this.querySelector('[data-ui-open]');
    const id = this.dataset.windowId || `xavi-ui-modal-${Math.random().toString(36).slice(2)}`;
    const title = this.dataset.windowTitle || this.config.modalTitle || 'Dialog';
    const managed = this.config.managedWindow !== false && Boolean(window.XaviFusionOS?.adoptModal) && dialog;
    const openOverlay = () => { overlay.hidden = false; document.body.classList.add('xavi-ui-overlay-open'); };
    const closeOverlay = () => { overlay.hidden = true; document.body.classList.remove('xavi-ui-overlay-open'); };
    if (this.editMode) { overlay.hidden = false; return; }
    const open = () => {
      if (managed) {
        overlay.hidden = true;
        window.XaviFusionOS.adoptModal({id,title,icon:'▣',workspace:this.getAttribute('workspace') || 'primary',element:dialog,width:Number(this.config.windowWidthPx || 760),height:Number(this.config.windowHeightPx || 560),minimizable:this.config.minimizable !== false,maximizable:this.config.maximizable !== false,rememberState:this.config.rememberWindowState !== false,scope:this.config.windowScope || 'workspace'});
      } else openOverlay();
    };
    const close = () => managed ? window.XaviFusionOS?.closeWindow?.(id) : closeOverlay();
    trigger?.addEventListener('click', open);
    this.querySelector('[data-ui-close]')?.addEventListener('click', close);
    if (!managed && this.config.closeOnBackdrop !== false) overlay?.addEventListener('click', event => { if (event.target === overlay) close(); });
    if (this.config.openOnLoad) queueMicrotask(open);
    const previousCleanup = this.cleanup;
