  content.style.setProperty('overflow', 'auto', 'important');
  shell?.style.setProperty('max-height', 'calc(100vh - 24px)', 'important');
}
function activateFusionEditorTab(editor, link, focus = false) {
  const selector = link?.getAttribute('href') || '';
  if (!/^#[A-Za-z][A-Za-z0-9_.:-]*$/.test(selector)) return false;
  const pane = editor.querySelector(selector);
  if (!pane) return false;
  editor.querySelectorAll('.nav-tabs li').forEach(item => item.classList.toggle('active', item.contains(link)));
  editor.querySelectorAll('.nav-tabs a[href^="#"]').forEach(item => {
    const active = item === link;
    item.classList.toggle('active', active);
    item.setAttribute('aria-selected', active ? 'true' : 'false');
    item.setAttribute('tabindex', active ? '0' : '-1');
  });
  editor.querySelectorAll('.tab-content > .tab-pane').forEach(item => {
    const active = item === pane;
    item.classList.toggle('active', active);
    item.classList.toggle('show', active);
    item.hidden = !active;
  });
  if (focus) link.focus({preventScroll:true});
  resizeFusionEditorDialog(editor);
  return true;
}
function initializeFusionEditor(editor) {
  if (!(editor instanceof Element)) return;
  const links = [...editor.querySelectorAll('.nav-tabs a[href^="#"]')];
  if (!links.length) return;
  links.forEach(link => {
    link.classList.add('nav-link');
    link.setAttribute('role', 'tab');
    link.setAttribute('data-bs-toggle', 'tab');
    link.removeAttribute('data-toggle');
  });
  const initial = links.find(link => link.classList.contains('active') || link.closest('li')?.classList.contains('active')) || links[0];
  activateFusionEditorTab(editor, initial, false);
  editor.dataset.fusionTabsReady = '1';
}
function initializeFusionEditors(root = document) {
  if (root instanceof Element && root.matches('.xavi-fusion-editor')) initializeFusionEditor(root);
  root.querySelectorAll?.('.xavi-fusion-editor').forEach(initializeFusionEditor);
}
document.addEventListener('click', event => {
  const link = event.target.closest?.(fusionEditorTabLinks);
  if (!link) return;
  const editor = link.closest('.xavi-fusion-editor');
  if (!editor) return;
  event.preventDefault();
  event.stopPropagation();
  activateFusionEditorTab(editor, link, false);
}, true);
document.addEventListener('keydown', event => {
  const link = event.target.closest?.(fusionEditorTabLinks);
  if (!link || !['ArrowLeft','ArrowRight','Home','End'].includes(event.key)) return;
  const editor = link.closest('.xavi-fusion-editor');
  const links = [...editor.querySelectorAll('.nav-tabs a[href^="#"]')];
  const index = links.indexOf(link);
  let next = index;
  if (event.key === 'ArrowLeft') next = (index - 1 + links.length) % links.length;
  if (event.key === 'ArrowRight') next = (index + 1) % links.length;
  if (event.key === 'Home') next = 0;
  if (event.key === 'End') next = links.length - 1;
  event.preventDefault();
  activateFusionEditorTab(editor, links[next], true);
}, true);
new MutationObserver(records => records.forEach(record => record.addedNodes.forEach(node => {
  if (node instanceof Element) initializeFusionEditors(node);
}))).observe(document.documentElement, {childList:true, subtree:true});
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => initializeFusionEditors());
else initializeFusionEditors();
