    public function discoverSources(): array
    {
        $this->ensureDirectories();
        $installed = [];
        foreach ($this->registry() as $row) {
            $installed[(string) $row['appID']] = $row;
        }
        $items = [];
        foreach (scandir($this->sourceRoot) ?: [] as $name) {
            if ($name === '.' || $name === '..' || str_starts_with($name, '.')) {
                continue;
            }
            $directory = $this->sourceRoot . '/' . $name;
            $manifestPath = $directory . '/fusion-app.json';
            if (!is_dir($directory) || is_link($directory) || !is_file($manifestPath)) {
                continue;
            }
            $item = [
                'directory' => $name,
                'path' => $directory,
                'valid' => false,
                'installed' => false,
                'updateAvailable' => false,
                'error' => '',
            ];
            try {
                $manifest = json_decode((string) file_get_contents($manifestPath), true, 512, JSON_THROW_ON_ERROR);
                if (!is_array($manifest) || ($manifest['format'] ?? '') !== 'xavi-fusion-app' || (int) ($manifest['formatVersion'] ?? 0) !== 1) {
                    throw new \\InvalidArgumentException(t('Invalid Fusion application manifest.'));
                }
                $id = $this->normalizeAppID((string) ($manifest['id'] ?? ''));
                $row = $installed[$id] ?? null;
                $installedManifest = $row ? json_decode((string) $row['manifestJson'], true) : null;
                $item += [
                    'id' => $id,
                    'version' => trim((string) ($manifest['version'] ?? '1.0.0')),
                    'title' => trim((string) ($manifest['title'] ?? $id)),
                    'description' => trim((string) ($manifest['description'] ?? '')),
                    'category' => trim((string) ($manifest['category'] ?? 'Applications')),
                    'component' => trim((string) (($manifest['entry']['component'] ?? null) ?: ($manifest['component'] ?? ''))),
                    'defaultEnabled' => !array_key_exists('defaultEnabled', $manifest) || filter_var($manifest['defaultEnabled'], FILTER_VALIDATE_BOOLEAN),
                    'valid' => true,
                    'installed' => (bool) $row,
                    'installedVersion' => $row ? (string) $row['version'] : '',
                    'enabledGlobal' => $row ? !empty($row['enabledGlobal']) : true,
                ];
                $item['updateAvailable'] = !$row || $this->manifestFingerprint($manifest) !== $this->manifestFingerprint(is_array($installedManifest) ? $installedManifest : []);
            } catch (\\Throwable $exc) {
                $item['error'] = $exc->getMessage();
            }
            $items[] = $item;
        }
        usort($items, static fn(array $a, array $b): int => strcasecmp((string) ($a['title'] ?? $a['directory']), (string) ($b['title'] ?? $b['directory'])));
        return $items;
    }

    public function syncTrustedSources(): array
    {
        $results = ['installed' => [], 'unchanged' => [], 'failed' => []];
        foreach ($this->discoverSources() as $source) {
            $directory = (string) ($source['directory'] ?? '');
            if (empty($source['valid'])) {
                $results['failed'][] = ['directory' => $directory, 'error' => (string) ($source['error'] ?? t('Invalid manifest.'))];
                continue;
            }
            if (!empty($source['installed']) && empty($source['updateAvailable'])) {
                $results['unchanged'][] = (string) $source['id'];
                continue;
            }
            $temp = $this->temporaryDirectory();
            try {
                $this->copyTree((string) $source['path'], $temp);
                $systemUser = new User();
                $results['installed'][] = $this->installPreparedDirectory($temp, 0, $systemUser, 0);
            } catch (\\Throwable $exc) {
                $results['failed'][] = ['directory' => $directory, 'error' => $exc->getMessage()];
            } finally {
                $this->removeTree($temp);
            }
        }
        return $results;
    }

    public function setGlobalState(string $appID, bool $enabled): void
    {
        $appID = $this->normalizeAppID($appID);
        if (!(int) $this->db->fetchOne('SELECT COUNT(*) FROM XaviFusionApplications WHERE appID = ?', [$appID])) {
            throw new \\RuntimeException(t('Fusion application not found.'));
        }
        $this->db->update('XaviFusionApplications', [
            'enabledGlobal' => $enabled ? 1 : 0,
            'updatedAt' => gmdate('Y-m-d H:i:s'),
        ], ['appID' => $appID]);
    }
