namespace Concrete\\Package\\XaviFusionOs\\Controller\\SinglePage\\Dashboard\\System\\XaviFusion;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\\Core\\Config\\Repository\\Repository;
use Concrete\\Core\\Page\\Controller\\DashboardPageController;
use Xavi\\FusionOS\\ApplicationPackageService;

class Apps extends DashboardPageController
{
    public function view()
    {
        $service = $this->app->make(ApplicationPackageService::class);
        $config = $this->app->make(Repository::class);
        $this->set('applications', $service->registry());
        $this->set('sources', $service->discoverSources());
        $this->set('sourceRoot', $service->sourceRoot());
        $this->set('autoSyncSources', (bool) $config->get('xavi_fusion_os.applications.auto_sync_sources', true));
        $this->set('startMenuEnabled', (bool) $config->get('xavi_fusion_os.applications.start_menu_enabled', true));
        $this->set('profilePinsEnabled', (bool) $config->get('xavi_fusion_os.applications.profile_pins_enabled', true));
        $this->set('refreshSeconds', max(15, min(3600, (int) $config->get('xavi_fusion_os.applications.refresh_seconds', 60))));
    }

    public function save()
    {
        if (!$this->token->validate('xavi_fusion_apps_settings')) {
            $this->error->add($this->token->getErrorMessage());
            return $this->view();
        }
        $config = $this->app->make(Repository::class);
        $config->save('xavi_fusion_os.applications.auto_sync_sources', (bool) $this->request->request->get('auto_sync_sources'));
        $config->save('xavi_fusion_os.applications.start_menu_enabled', (bool) $this->request->request->get('start_menu_enabled'));
        $config->save('xavi_fusion_os.applications.profile_pins_enabled', (bool) $this->request->request->get('profile_pins_enabled'));
        $config->save('xavi_fusion_os.applications.refresh_seconds', max(15, min(3600, (int) $this->request->request->get('refresh_seconds', 60))));
        $this->flash('success', t('Taskbar and application settings saved.'));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }

    public function sync()
    {
        if (!$this->token->validate('xavi_fusion_apps_sync')) {
            $this->error->add($this->token->getErrorMessage());
            return $this->view();
        }
        $result = $this->app->make(ApplicationPackageService::class)->syncTrustedSources();
        $message = t('%s application package(s) installed or updated; %s unchanged; %s failed.', count($result['installed']), count($result['unchanged']), count($result['failed']));
        if (!empty($result['failed'])) {
            $this->error->add($message . ' ' . implode(' ', array_map(static fn(array $item): string => (string) ($item['directory'] ?? '') . ': ' . (string) ($item['error'] ?? ''), $result['failed'])));
            return $this->view();
        }
        $this->flash('success', $message);
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }

    public function global_state()
    {
        if (!$this->token->validate('xavi_fusion_apps_global_state')) {
            $this->error->add($this->token->getErrorMessage());
            return $this->view();
        }
        $appID = (string) $this->request->request->get('app_id', '');
        $enabled = (bool) $this->request->request->get('enabled');
        $this->app->make(ApplicationPackageService::class)->setGlobalState($appID, $enabled);
        $this->flash('success', $enabled ? t('Application enabled globally.') : t('Application disabled globally.'));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }
}
''')

