namespace Concrete\\Package\\XaviFusionOs\\Controller\\SinglePage\\Account;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\\Core\\Page\\Controller\\PageController;
use Concrete\\Core\\User\\User;
use Symfony\\Component\\HttpFoundation\\RedirectResponse;
use Xavi\\FusionOS\\ApplicationPackageService;
use Xavi\\FusionOS\\ScopeResolver;

class XaviProfile extends PageController
{
    public function view()
    {
        $user = new User();
        if (!$user->isRegistered()) {
            return new RedirectResponse('/login/forward?rcURL=' . rawurlencode('/account/xavi-profile'));
        }
        $groups = [];
        $scopes = [];
        $applications = [];
        $applicationError = '';
        try {
            $resolver = $this->app->make(ScopeResolver::class);
            $groups = $resolver->groupNames($user);
            $scopes = $resolver->resolve($user);
        } catch (\\Throwable $exc) {
            $applicationError = t('Your identity information could not be loaded completely.');
        }
        try {
            $applications = $this->app->make(ApplicationPackageService::class)->listForUser($user, true);
        } catch (\\Throwable $exc) {
            $applicationError = t('Your applications are temporarily unavailable. Your profile and security settings are still accessible.');
        }
        $this->set('fusionUser', $user);
        $this->set('groups', $groups);
        $this->set('scopes', $scopes);
        $this->set('applications', $applications);
        $this->set('applicationError', $applicationError);
        $this->set('isSuperUser', $user->isSuperUser());
    }
}
''')

