p.write_text('''<?php
namespace Concrete\\Package\\XaviFusionOs\\Controller\\SinglePage\\Dashboard\\System\\XaviFusion;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\\Core\\Config\\Repository\\Repository;
use Concrete\\Core\\Page\\Controller\\DashboardPageController;
use Concrete\\Core\\Page\\Page;
use Concrete\\Core\\User\\User;
use Symfony\\Component\\HttpFoundation\\File\\UploadedFile;
use Xavi\\FusionOS\\ApplicationPackageService;

class Apps extends DashboardPageController
{
    public function view()
    {
        $service = $this->app->make(ApplicationPackageService::class);
        $config = $this->app->make(Repository::class);
        $this->set('applications', $service->registry());
        $this->set('sources', $service->discoverSources());
        $this->set('sourceRoot', $service->sourceRoot());
        $this->set('startMenuEnabled', (bool) $config->get('xavi_fusion_os.applications.start_menu_enabled', true));
        $this->set('profilePinsEnabled', (bool) $config->get('xavi_fusion_os.applications.profile_pins_enabled', true));
        $this->set('refreshSeconds', max(15, min(3600, (int) $config->get('xavi_fusion_os.applications.refresh_seconds', 60))));
        $this->set('redirectAccountWelcome', (bool) $config->get('xavi_fusion_os.account.redirect_welcome', true));
    }

    public function save()
    {
        $this->requireAdmin();
        if (!$this->token->validate('xavi_fusion_apps_settings')) { $this->error->add($this->token->getErrorMessage()); return $this->view(); }
        $config = $this->app->make(Repository::class);
        $config->save('xavi_fusion_os.applications.start_menu_enabled', (bool) $this->request->request->get('start_menu_enabled'));
        $config->save('xavi_fusion_os.applications.profile_pins_enabled', (bool) $this->request->request->get('profile_pins_enabled'));
        $config->save('xavi_fusion_os.applications.refresh_seconds', max(15, min(3600, (int) $this->request->request->get('refresh_seconds', 60))));
        $config->save('xavi_fusion_os.account.redirect_welcome', (bool) $this->request->request->get('redirect_account_welcome'));
        $this->flash('success', t('Taskbar, application, and account navigation settings saved.'));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }

    public function install_source()
    {
        $user = $this->requireAdmin();
        if (!$this->token->validate('xavi_fusion_app_install_source')) { $this->error->add($this->token->getErrorMessage()); return $this->view(); }
        $directory = trim((string) $this->request->request->get('directory', ''));
        $result = $this->app->make(ApplicationPackageService::class)->installDirectory($directory, $this->dashboardPageID(), $user);
        $this->flash('success', t('Installed %s %s.', $result['title'] ?? $result['id'], $result['version']));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }

    public function sync_sources()
    {
        $user = $this->requireAdmin();
        if (!$this->token->validate('xavi_fusion_app_sync_sources')) { $this->error->add($this->token->getErrorMessage()); return $this->view(); }
        $service = $this->app->make(ApplicationPackageService::class);
        $installed = [];
        $failed = [];
        foreach ($service->discoverSources() as $source) {
            if (empty($source['valid']) || (empty($source['updateAvailable']) && !empty($source['installed']))) continue;
            try { $installed[] = $service->installDirectory((string) $source['directory'], $this->dashboardPageID(), $user); }
            catch (\\Throwable $exc) { $failed[] = ($source['directory'] ?? '?') . ': ' . $exc->getMessage(); }
        }
        if ($failed) $this->error->add(t('Some sources failed: %s', implode('; ', $failed)));
        if ($installed) $this->flash('success', t('Installed or updated %s Fusion application source(s).', count($installed)));
        elseif (!$failed) $this->flash('success', t('All discovered sources are already synchronized.'));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }

    public function upload()
    {
        $user = $this->requireAdmin();
        if (!$this->token->validate('xavi_fusion_app_upload')) { $this->error->add($this->token->getErrorMessage()); return $this->view(); }
        $file = $this->request->files->get('fusion_app');
        if (!$file instanceof UploadedFile) throw new \\InvalidArgumentException(t('Choose a .xaviapp or ZIP file.'));
        $result = $this->app->make(ApplicationPackageService::class)->installUploaded($file, $this->dashboardPageID(), $user);
        $this->flash('success', t('Installed %s %s.', $result['title'] ?? $result['id'], $result['version']));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }

    public function global_state()
    {
        $this->requireAdmin();
        if (!$this->token->validate('xavi_fusion_app_global_state')) { $this->error->add($this->token->getErrorMessage()); return $this->view(); }
        $this->app->make(ApplicationPackageService::class)->setGlobalState((string) $this->request->request->get('app_id', ''), (bool) $this->request->request->get('enabled'));
        $this->flash('success', t('Global application state updated.'));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/apps');
    }

    private function requireAdmin(): User
    {
        $user = new User();
        if (!$user->isRegistered() || !$user->isSuperUser()) throw new \\RuntimeException(t('Administrator access is required.'));
        return $user;
    }

    private function dashboardPageID(): int
    {
        $page = Page::getByPath('/dashboard/system/xavi-fusion/apps');
        if (!$page || $page->isError()) throw new \\RuntimeException(t('The Fusion Applications dashboard page is unavailable.'));
        return (int) $page->getCollectionID();
    }
}
''')

