<?php
namespace Xavi\FusionOS;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\Core\Config\Repository\Repository;
use Concrete\Core\Controller\Controller;
use Concrete\Core\Http\Request;
use Concrete\Core\User\User;
use Symfony\Component\HttpFoundation\JsonResponse;

class ChatHttpController extends Controller
{
    private Repository $config;

    public function __construct(Request $request, Repository $config)
    {
        parent::__construct();
        $this->request = $request;
        $this->config = $config;
    }

    public function config(): JsonResponse
    {
        try {
            $user = $this->registered();
            return new JsonResponse([
                'enabled' => (bool) $this->config->get('xavi_fusion_os.chat.enabled', true),
                'footerEnabled' => (bool) $this->config->get('xavi_fusion_os.chat.footer_enabled', true),
                'websocketEnabled' => (bool) $this->config->get('xavi_fusion_os.chat.websocket_enabled', true),
                'chatHeadsEnabled' => (bool) $this->config->get('xavi_fusion_os.chat.chat_heads_enabled', true),
                'soundEnabled' => (bool) $this->config->get('xavi_fusion_os.chat.sound_enabled', true),
                'directMessagesEnabled' => (bool) $this->config->get('xavi_fusion_os.chat.direct_messages_enabled', true),
                'maxMessageLength' => max(256, min(32000, (int) $this->config->get('xavi_fusion_os.chat.max_message_length', 8000))),
                'maxGroupSize' => max(2, min(500, (int) $this->config->get('xavi_fusion_os.chat.max_group_size', 100))),
                'pollSeconds' => max(5, min(300, (int) $this->config->get('xavi_fusion_os.chat.poll_seconds', 15))),
                'apiBase' => '/api/v1/chat',
                'websocketPath' => '/api/v1/chat/ws',
                'tokenUrl' => '/xavi-fusion/api/token',
                'directoryUrl' => '/xavi-fusion/api/chat/directory',
                'dashboardUrl' => '/dashboard/system/xavi-fusion/chat',
                'user' => [
                    'id' => (int) $user->getUserID(),
                    'username' => (string) $user->getUserName(),
                    'administrator' => (bool) $user->isSuperUser(),
                ],
            ], 200, ['Cache-Control' => 'no-store']);
        } catch (\Throwable $exc) {
            return new JsonResponse(['error' => $exc->getMessage()], 401, ['Cache-Control' => 'no-store']);
        }
    }

    public function directory(): JsonResponse
    {
        try {
            $user = $this->registered();
            if (!(bool) $this->config->get('xavi_fusion_os.chat.enabled', true)) {
                return new JsonResponse(['items' => []], 200, ['Cache-Control' => 'no-store']);
            }
            $query = trim((string) $this->request->query->get('q', ''));
            $limit = max(1, min(100, (int) $this->request->query->get('limit', 50)));
            $params = [(int) $user->getUserID()];
            $where = 'uIsActive = 1 AND uID <> ?';
            if ($query !== '') {
                $where .= ' AND uName LIKE ?';
                $params[] = '%' . str_replace(['%', '_'], ['\\%', '\\_'], $query) . '%';
            }
            $params[] = $limit;
            $rows = app('database')->connection()->fetchAllAssociative(
                "SELECT uID, uName, uDateAdded, uLastOnline FROM Users WHERE {$where} ORDER BY uLastOnline DESC, uName ASC LIMIT ?",
                $params
            );
            $items = array_map(static function (array $row): array {
                return [
                    'id' => (string) ((int) $row['uID']),
                    'username' => (string) $row['uName'],
                    'displayName' => (string) $row['uName'],
                    'profileUrl' => '/members/profile/' . rawurlencode((string) $row['uName']),
                    'joinedAt' => (string) ($row['uDateAdded'] ?? ''),
                    'lastOnline' => (string) ($row['uLastOnline'] ?? ''),
                ];
            }, $rows);
            return new JsonResponse(['items' => $items], 200, ['Cache-Control' => 'no-store']);
        } catch (\Throwable $exc) {
            return new JsonResponse(['error' => $exc->getMessage()], 401, ['Cache-Control' => 'no-store']);
        }
    }

    private function registered(): User
    {
        $user = new User();
        if (!$user->isRegistered()) {
            throw new \RuntimeException(t('A registered Concrete CMS user is required.'));
        }
        return $user;
    }
}
