<?php
namespace Concrete\Package\XaviFusionOs\Controller\SinglePage\Dashboard\System\XaviFusion;

defined('C5_EXECUTE') or die('Access Denied.');

use Concrete\Core\Config\Repository\Repository;
use Concrete\Core\Page\Controller\DashboardPageController;
use Concrete\Core\User\User;

class Chat extends DashboardPageController
{
    public function view()
    {
        $config = $this->app->make(Repository::class);
        foreach ($this->keys() as $name => [$key, $default]) {
            $this->set($name, $config->get($key, $default));
        }
    }

    public function save()
    {
        $user = new User();
        if (!$user->isRegistered() || !$user->isSuperUser()) {
            throw new \RuntimeException(t('Administrator access is required.'));
        }
        if (!$this->token->validate('xavi_fusion_chat_settings')) {
            $this->error->add($this->token->getErrorMessage());
            return $this->view();
        }
        $config = $this->app->make(Repository::class);
        foreach ([
            'enabled', 'footer_enabled', 'websocket_enabled', 'chat_heads_enabled',
            'sound_enabled', 'direct_messages_enabled',
        ] as $boolean) {
            $config->save('xavi_fusion_os.chat.' . $boolean, (bool) $this->request->request->get($boolean));
        }
        $config->save('xavi_fusion_os.chat.max_message_length', max(256, min(32000, (int) $this->request->request->get('max_message_length', 8000))));
        $config->save('xavi_fusion_os.chat.max_group_size', max(2, min(500, (int) $this->request->request->get('max_group_size', 100))));
        $config->save('xavi_fusion_os.chat.poll_seconds', max(5, min(300, (int) $this->request->request->get('poll_seconds', 15))));
        $config->save('xavi_fusion_os.chat.retention_days', max(1, min(3650, (int) $this->request->request->get('retention_days', 365))));
        $this->flash('success', t('Messenger settings saved.'));
        return $this->buildRedirect('/dashboard/system/xavi-fusion/chat');
    }

    private function keys(): array
    {
        return [
            'chatEnabled' => ['xavi_fusion_os.chat.enabled', true],
            'footerEnabled' => ['xavi_fusion_os.chat.footer_enabled', true],
            'websocketEnabled' => ['xavi_fusion_os.chat.websocket_enabled', true],
            'chatHeadsEnabled' => ['xavi_fusion_os.chat.chat_heads_enabled', true],
            'soundEnabled' => ['xavi_fusion_os.chat.sound_enabled', true],
            'directMessagesEnabled' => ['xavi_fusion_os.chat.direct_messages_enabled', true],
            'maxMessageLength' => ['xavi_fusion_os.chat.max_message_length', 8000],
            'maxGroupSize' => ['xavi_fusion_os.chat.max_group_size', 100],
            'pollSeconds' => ['xavi_fusion_os.chat.poll_seconds', 15],
            'retentionDays' => ['xavi_fusion_os.chat.retention_days', 365],
        ];
    }
}
