 async ensureToken(force=false){const now=Math.floor(Date.now()/1000);if(!force&&this.token&&this.tokenExpires>now+60)return this.token;const response=await fetch(this.config?.tokenUrl||'/xavi-fusion/api/token',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});if(!response.ok){const text=await response.text();throw new Error(`Messenger authentication failed (${response.status}) ${text.slice(0,120)}`);}const payload=await response.json();this.token=payload.access_token;this.tokenExpires=Number(payload.expires_at||now+Number(payload.expires_in||300));return this.token;}
 async api(path,options={},retry=true){await this.ensureToken();const headers=new Headers(options.headers||{});headers.set('Accept','application/json');headers.set('Authorization',`Bearer ${this.token}`);if(options.body&&!(options.body instanceof FormData))headers.set('Content-Type','application/json');const response=await fetch(`${this.config?.apiBase||'/api/v1/chat'}${path}`,{...options,headers,credentials:'same-origin'});if(response.status===401&&retry){await this.ensureToken(true);return this.api(path,options,false);}if(!response.ok){let message=`Messenger request failed (${response.status})`;try{const payload=await response.json();message=payload.detail||payload.error||message;}catch{}throw new Error(message);}if(response.status===204)return null;return response.json();}
 socketUrl(){const scheme=location.protocol==='https:'?'wss:':'ws:';return `${scheme}//${location.host}${this.config.websocketPath||'/api/v1/chat/ws'}`;}
 async connectSocket(){clearTimeout(this.reconnectTimer);if(!this.config?.enabled||!this.config.websocketEnabled)return;await this.ensureToken();if(this.socket&&[WebSocket.OPEN,WebSocket.CONNECTING].includes(this.socket.readyState))return;this.socketState='connecting';this.emit();try{const socket=new WebSocket(this.socketUrl(),['xavi-chat-v1',this.token]);this.socket=socket;socket.onopen=()=>{this.socketState='online';this.reconnectAttempts=0;this.emit();socket.send(JSON.stringify({type:'ping'}));};socket.onmessage=e=>{try{this.onEvent(JSON.parse(e.data));}catch{}};socket.onerror=()=>{this.socketState='error';this.emit();};socket.onclose=()=>{if(this.socket===socket)this.socket=null;this.socketState='offline';this.emit();this.scheduleReconnect();};}catch(error){this.socketState='error';this.emit('error',{error});this.scheduleReconnect();}}
 scheduleReconnect(){clearTimeout(this.reconnectTimer);if(!this.config?.websocketEnabled)return;const delay=Math.min(30000,1000*2**Math.min(5,this.reconnectAttempts++));this.reconnectTimer=setTimeout(()=>this.connectSocket(),delay);}
 startPolling(){clearInterval(this.pollTimer);const seconds=Math.max(5,Number(this.config?.pollSeconds||15));this.pollTimer=setInterval(()=>this.refreshConversations().catch(()=>{}),seconds*1000);}
 async refreshConversations(){if(!this.config?.enabled)return;const items=await this.api('/conversations');this.conversations=items;this.emit();}
 async loadMessages(conversationId,force=false){const id=String(conversationId);if(!force&&this.messages.has(id))return this.messages.get(id);const rows=await this.api(`/conversations/${encodeURIComponent(id)}/messages?limit=100`);this.messages.set(id,rows);this.activeConversation=id;await this.markRead(id);this.emit();return rows;}
 async markRead(id){const result=await this.api(`/conversations/${encodeURIComponent(id)}/read`,{method:'POST'});const conversation=this.conversations.find(x=>String(x.id)===String(id));if(conversation){conversation.unread_count=0;conversation.last_read_message_id=result.message_id;}this.broadcast({type:'read',conversationId:String(id)});this.emit();}
 async send(id,body,extra={}){const text=String(body||'').trim();if(!text&&!extra.attachment)return;const message=await this.api(`/conversations/${encodeURIComponent(id)}/messages`,{method:'POST',body:JSON.stringify({body:text,kind:extra.kind||'text',reply_to_message_id:extra.replyTo||null,attachment:extra.attachment||{}})});this.upsertMessage(String(id),message);this.emit();return message;}
 async createDirect(person){const conversation=await this.api('/direct',{method:'POST',body:JSON.stringify({user_id:String(person.id),username:person.username,display_name:person.displayName||person.username})});this.upsertConversation(conversation);await this.loadMessages(conversation.id,true);this.broadcast({type:'conversation',conversation});return conversation;}
 async createGroup(title,participants){const conversation=await this.api('/groups',{method:'POST',body:JSON.stringify({title,participants:participants.map(p=>({user_id:String(p.id),username:p.username,display_name:p.displayName||p.username}))})});this.upsertConversation(conversation);await this.loadMessages(conversation.id,true);this.broadcast({type:'conversation',conversation});return conversation;}
 async searchDirectory(query=''){const response=await fetch(`${this.config.directoryUrl}?q=${encodeURIComponent(query)}&limit=80`,{credentials:'same-origin',headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Member directory failed (${response.status})`);this.directory=(await response.json()).items||[];this.emit();return this.directory;}
 async react(messageId,emoji,active=true){const message=await this.api(`/messages/${messageId}/reaction`,{method:'POST',body:JSON.stringify({emoji,active})});this.upsertMessage(String(message.conversation_id),message);this.emit();}
