class MessengerView extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.tab='chats';this.selected='';this.search='';this.loading=false;this.error='';this._change=()=>this.render();}
 connectedCallback(){client.addEventListener('change',this._change);client.addEventListener('error',e=>{this.error=e.detail.error?.message||String(e.detail.error);this.render()});client.init().then(()=>{if(client.activeConversation)this.select(client.activeConversation);else this.render()}).catch(()=>{});this.render();}
