 conversation(){return client.conversations.find(x=>String(x.id)===String(this.selected));}
 render(){const c=this.conversation(),rows=client.messages.get(this.selected)||[];this.shadowRoot.innerHTML=`<link rel="stylesheet" href="/packages/xavi_fusion_os/css/messenger.css"><div class="messenger-shell"><aside class="messenger-sidebar"><header><div><h2>Messenger</h2><small><i class="state ${esc(client.socketState)}"></i>${esc(client.socketState)}</small></div><button data-new title="New conversation">＋</button></header><label class="search"><span>⌕</span><input data-search placeholder="Search conversations" value="${esc(this.search)}"></label><nav class="tabs"><button data-tab="chats" class="${this.tab==='chats'?'active':''}">Chats</button><button data-tab="people" class="${this.tab==='people'?'active':''}">People</button><button data-tab="settings" class="${this.tab==='settings'?'active':''}">Settings</button></nav><div class="sidebar-body">${this.sidebar()}</div></aside><main class="messenger-main">${c?this.thread(c,rows):this.empty()}</main></div>`;this.bind();}
 sidebar(){if(this.tab==='people')return this.people();if(this.tab==='settings')return this.settingsView();const q=this.search.toLowerCase();const conversations=client.conversations.filter(c=>!q||client.conversationName(c).toLowerCase().includes(q));return conversations.map(c=>{const name=client.conversationName(c),other=(c.participants||[]).find(x=>String(x.user_id)!==String(client.user?.id)),online=other&&client.online.get(String(other.user_id))?.online,last=c.last_message;return `<button class="conversation ${String(c.id)===this.selected?'active':''}" data-conversation="${esc(c.id)}"><span class="avatar">${esc(initials(name))}<i class="presence ${online?'online':''}"></i></span><span class="conversation-copy"><strong>${esc(name)}</strong><small>${esc(last?.deleted_at?'Message removed':last?.body||'No messages yet')}</small></span>${Number(c.unread_count||0)>0?`<b class="unread">${Number(c.unread_count)}</b>`:''}</button>`}).join('')||'<p class="blank">No conversations yet.</p>';}
