 settingsView(){const s=client.settings||{};return `<form class="messenger-settings" data-settings><label>Availability<select name="availability">${['online','away','busy','offline'].map(v=>`<option ${s.availability===v?'selected':''}>${v}</option>`).join('')}</select></label>${[['allow_direct_messages','Allow direct messages'],['read_receipts','Read receipts'],['sound_enabled','Notification sounds'],['footer_enabled','Footer messenger'],['chat_heads_enabled','Chat heads'],['compact_mode','Compact mode']].map(([k,l])=>`<label class="check"><input type="checkbox" name="${k}" ${s[k]!==false?'checked':''}>${l}</label>`).join('')}<button type="submit">Save preferences</button>${client.user?.is_admin?'<a href="/dashboard/system/xavi-fusion/chat">Administrator settings</a>':''}</form>`;}
 empty(){return `<section class="messenger-empty"><div class="big-logo">✦</div><h2>Your messages</h2><p>Choose a conversation or start one with another registered member.</p><button data-empty-new>New message</button></section>`;}
 thread(c,rows){const name=client.conversationName(c),typing=[...(client.typing.get(String(c.id))||new Map()).values()].filter(x=>x!==client.user?.username);return `<header class="thread-header"><span class="avatar">${esc(initials(name))}</span><div><h2>${esc(name)}</h2><small>${typing.length?`${esc(typing.join(', '))} typing…`:`${(c.participants||[]).length} participant${(c.participants||[]).length===1?'':'s'}`}</small></div><button data-thread-info>ⓘ</button></header><div class="messages" data-messages>${this.loading?'<p class="loading">Loading messages…</p>':rows.map(m=>this.message(m)).join('')||'<p class="blank">No messages yet. Say hello.</p>'}</div><form class="composer" data-composer><button type="button" data-emoji>☺</button><textarea name="body" rows="1" maxlength="${Number(client.config?.maxMessageLength||8000)}" placeholder="Message ${esc(name)}"></textarea><button type="submit" class="send">➤</button></form>`;}
 message(m){const mine=String(m.sender_id)===String(client.user?.id),deleted=Boolean(m.deleted_at),reactions=(m.reactions||[]).reduce((map,r)=>(map[r.emoji]=(map[r.emoji]||0)+1,map),{});return `<article class="message ${mine?'mine':''} ${deleted?'deleted':''}" data-message="${Number(m.id)}"><span class="message-avatar">${esc(initials(m.sender_username))}</span><div><small>${esc(m.sender_username)} · ${esc(fmt(m.created_at))}${m.edited_at?' · edited':''}</small><p>${deleted?'<em>Message removed</em>':esc(m.body)}</p>${Object.entries(reactions).length?`<div class="reactions">${Object.entries(reactions).map(([e,n])=>`<button data-reaction="${esc(e)}">${esc(e)} ${n}</button>`).join('')}</div>`:''}<div class="message-actions"><button data-add-reaction="👍">👍</button><button data-add-reaction="❤️">❤️</button>${mine&&!deleted?'<button data-delete>Delete</button>':''}</div></div></article>`;}
 bind(){const r=this.shadowRoot;r.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>this.select(b.dataset.conversation));r.querySelectorAll('[data-tab]').forEach(b=>b.onclick=async()=>{this.tab=b.dataset.tab;if(this.tab==='people'&&!client.directory.length)await client.searchDirectory('');this.render()});const search=r.querySelector('[data-search]');if(search)search.oninput=e=>{this.search=e.target.value;this.render()};const psearch=r.querySelector('[data-person-search]');if(psearch){let timer;psearch.oninput=e=>{this.search=e.target.value;clearTimeout(timer);timer=setTimeout(()=>client.searchDirectory(this.search).catch(x=>{this.error=x.message}),250)}}r.querySelectorAll('[data-person]').forEach(b=>b.onclick=async()=>{const person=client.directory.find(x=>String(x.id)===b.dataset.person);if(person){const c=await client.createDirect(person);this.tab='chats';this.select(c.id)}});const composer=r.querySelector('[data-composer]');if(composer){const area=composer.querySelector('textarea');let typingTimer;area.oninput=()=>{client.typingEvent(this.selected,true);clearTimeout(typingTimer);typingTimer=setTimeout(()=>client.typingEvent(this.selected,false),1200)};composer.onsubmit=async e=>{e.preventDefault();const body=area.value.trim();if(!body)return;area.value='';client.typingEvent(this.selected,false);try{await client.send(this.selected,body);this.render();this.scrollBottom()}catch(x){this.error=x.message;this.render()}}}r.querySelectorAll('[data-add-reaction]').forEach(b=>b.onclick=()=>client.react(Number(b.closest('[data-message]').dataset.message),b.dataset.addReaction,true));r.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this message?'))return;await client.api(`/messages/${b.closest('[data-message]').dataset.message}`,{method:'DELETE'})});const settings=r.querySelector('[data-settings]');if(settings)settings.onsubmit=async e=>{e.preventDefault();const patch={};for(const field of new FormData(settings))patch[field[0]]=field[1];settings.querySelectorAll('input[type=checkbox]').forEach(x=>patch[x.name]=x.checked);await client.updateSettings(patch);};const newButtons=[r.querySelector('[data-new]'),r.querySelector('[data-empty-new]')].filter(Boolean);newButtons.forEach(b=>b.onclick=async()=>{this.tab='people';await client.searchDirectory('');this.render()});const group=r.querySelector('[data-group]');if(group)group.onclick=async()=>{const title=prompt('Group name');if(!title)return;const usernames=prompt('Member usernames, comma separated')?.split(',').map(x=>x.trim()).filter(Boolean)||[];const people=client.directory.filter(p=>usernames.includes(p.username));if(!people.length)return alert('No matching users selected.');const c=await client.createGroup(title,people);this.tab='chats';this.select(c.id)};r.querySelector('[data-emoji]')?.addEventListener('click',()=>{const a=r.querySelector('[data-composer] textarea');a.value+=' 😊';a.focus()});this.scrollBottom();}
 scrollBottom(){requestAnimationFrame(()=>{const box=this.shadowRoot.querySelector('[data-messages]');if(box)box.scrollTop=box.scrollHeight})}
}

