 bind(){const r=this.shadowRoot;r.querySelector('[data-launch]')?.addEventListener('click',()=>{this.opened=!this.opened;this.render()});r.querySelector('[data-close]')?.addEventListener('click',()=>{this.opened=false;this.render()});r.querySelector('[data-full]')?.addEventListener('click',()=>client.open());r.querySelector('[data-new]')?.addEventListener('click',()=>client.open());r.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>{client.open(b.dataset.chat);this.opened=false;this.render()})}
